{
  "id": "V026",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "공급사 설명의 상품 정보를 정리하려는 목적이 보존되었습니다."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "속성을 파악·추출하고 품목별로 정리하는 동작이 보존되었습니다."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "재질, 크기, 색상, 관리 방법 등 상품 속성이 보존되었습니다."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "공급사가 보낸 설명이 입력으로 보존되었습니다."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "품목별 검토용 표와 누락 속성의 미상 표시가 보존되었습니다."
    },
    {
      "field": "constraints",
      "score": 0,
      "reason": "판매 가격을 바꾸지 않고 확인되지 않은 성능을 덧붙이지 않는 제약이 모든 뷰에서 빠졌습니다."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "뷰에 원문에 없는 기능이 추가되지 않았습니다."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "공급사 설명을 처리하는 상품 속성 정리 맥락이 보존되었으며 역할 변경이 없습니다."
    }
  ],
  "issues": [
    {
      "type": "OMISSION",
      "source_quote": "판매 가격을 바꾸거나",
      "view_quote": "",
      "reason": "가격을 변경하지 않는 제약이 모든 뷰에서 누락되었습니다."
    },
    {
      "type": "OMISSION",
      "source_quote": "공급사에 확인되지 않은 성능을 덧붙이지 않습니다.",
      "view_quote": "",
      "reason": "확인되지 않은 성능을 추가하지 않는 제약이 모든 뷰에서 누락되었습니다."
    }
  ],
  "permission_interpretation": "원문은 가격 변경과 미확인 성능 추가를 금지하며, 뷰에 해당 제약은 나타나지 않습니다."
}
